var e=JSON.parse(`[{"id":"01-a1b2c3d4","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"medium","question":"A financial services company runs a critical trading application on RDS MySQL in us-east-1. RTO is 5 minutes, RPO is 1 minute. Regulatory requirements prohibit storing data outside the US. Which configuration meets these requirements at the lowest complexity?","options":{"A":"Enable RDS Multi-AZ in us-east-1 with automated backups to S3","B":"Deploy RDS read replicas in us-west-2 with manual failover procedures","C":"Use RDS Multi-AZ in us-east-1 and cross-region replication to us-west-1","D":"Run two independent RDS instances in different AZs with application-level replication"},"correct":"A","explanation":"RDS Multi-AZ provides synchronous replication to a standby in a different AZ within the same region, with automatic failover typically completing in 1-2 minutes — well within the 5-minute RTO. Automated backups give sub-1-minute RPO. Both AZs are in us-east-1, so data stays within the US. This is the simplest solution that meets all constraints.","distractors":{"B":"Cross-region read replicas replicate asynchronously and require manual promotion, making RTO unpredictable.","C":"Cross-region replication adds unnecessary complexity and potentially violates single-region data residency requirements.","D":"Application-level replication is complex, error-prone, and provides no automated failover."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.MultiAZ.html","tags":["rds","multi-az","failover","rto","rpo"],"verified":true},{"id":"01-b2c3d4e5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"hard","question":"A global e-commerce company needs its product catalog API to survive a complete AWS region failure with RTO under 15 minutes and RPO under 60 seconds. The API is read-heavy at 100:1 read-to-write ratio. Which architecture best meets these requirements?","options":{"A":"Aurora Global Database with a secondary region and Route 53 health checks for DNS failover","B":"RDS Multi-AZ in primary region with cross-region snapshots every 15 minutes","C":"DynamoDB Global Tables with Route 53 latency-based routing","D":"ElastiCache Redis with cross-region replication and CloudFront caching"},"correct":"A","explanation":"Aurora Global Database replicates with typical lag under 1 second, meeting the 60-second RPO. Promotion of a secondary region completes in under a minute, and Route 53 health checks automate DNS failover to meet the 15-minute RTO. Aurora read replicas efficiently serve the read-heavy workload. This is the purpose-built AWS solution for relational cross-region HA.","distractors":{"B":"Cross-region snapshots every 15 minutes means up to 15 minutes of data loss (RPO violation) and restoration takes far longer than 15 minutes (RTO violation).","C":"DynamoDB Global Tables suits key-value workloads; product catalogs with complex relational queries are better served by Aurora.","D":"ElastiCache is a caching layer, not a primary data store, and cannot serve as the authoritative source for the catalog."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database.html","tags":["aurora","global-database","multi-region","route53","rto","rpo"],"verified":true},{"id":"01-c3d4e5f6","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"easy","question":"Which statement correctly describes the primary difference between Multi-AZ and Multi-Region deployments in AWS?","options":{"A":"Multi-AZ protects against datacenter failures within one region; Multi-Region protects against regional outages","B":"Multi-AZ is only available for RDS; Multi-Region is available for all services","C":"Multi-AZ replicates asynchronously; Multi-Region replicates synchronously","D":"Multi-AZ requires manual failover; Multi-Region provides automatic failover"},"correct":"A","explanation":"Multi-AZ deploys resources across multiple Availability Zones within a single AWS Region, protecting against datacenter-level failures while keeping latency low. Multi-Region architectures span geographically separate regions to protect against regional outages at the cost of higher latency and operational complexity.","distractors":{"B":"Multi-AZ is available for many services beyond RDS including ElastiCache, EFS, and ALB.","C":"RDS Multi-AZ uses synchronous replication; many Multi-Region options use asynchronous replication — the opposite of what's stated.","D":"RDS Multi-AZ provides automatic failover; most Multi-Region failovers require manual promotion or Route 53 automation."},"source_url":"https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-options-in-the-cloud.html","tags":["multi-az","multi-region","disaster-recovery"],"verified":true},{"id":"01-d4e5f6a7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"medium","question":"A company's application writes to DynamoDB and must continue operating if an entire AWS Region becomes unavailable. Writes must succeed in another region within 30 seconds of regional failure. Which solution meets this?","options":{"A":"DynamoDB Global Tables with Route 53 health checks for automatic traffic failover","B":"DynamoDB with cross-region snapshots restored to a new table on failure","C":"DynamoDB Streams replicating via Lambda to a second region","D":"DynamoDB with daily backups using AWS Backup replicated cross-region"},"correct":"A","explanation":"DynamoDB Global Tables provides active-active multi-region replication with sub-second lag. Route 53 health checks reroute traffic when the primary region fails, enabling writes to resume in the secondary region within seconds — well under the 30-second requirement. The application uses the same DynamoDB API in any region.","distractors":{"B":"Restoring a DynamoDB snapshot takes minutes to hours depending on table size, far exceeding the 30-second requirement.","C":"Streams with Lambda introduces additional latency and operational complexity versus the managed Global Tables solution.","D":"Daily backups mean up to 24 hours of data loss and restoration time far exceeds 30 seconds."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["dynamodb","global-tables","multi-region","failover"],"verified":true},{"id":"01-e5f6a7b8","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"medium","question":"A startup runs its entire stack in a single AZ. The CTO requires 99.99% availability. What is the MOST cost-effective first step?","options":{"A":"Duplicate the entire stack to a second AWS Region","B":"Distribute the application across at least two Availability Zones in the same region","C":"Purchase Reserved Instances in multiple regions","D":"Enable AWS CloudTrail and Config for compliance monitoring"},"correct":"B","explanation":"Moving to two AZs within the same region is the most cost-effective path to high availability. Services like ALB, Auto Scaling, and RDS Multi-AZ natively support multi-AZ deployment. A single-region, multi-AZ architecture achieves 99.99%+ availability at a fraction of the cost of multi-region.","distractors":{"A":"Multi-region redundancy is expensive and complex; disproportionate as a first step when multi-AZ achieves the availability target.","C":"Reserved Instances affect cost but have no impact on availability.","D":"CloudTrail and Config are governance tools; they do not improve uptime."},"source_url":"https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html","tags":["availability-zones","high-availability","cost"],"verified":true},{"id":"01-f6a7b8c9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Multi-AZ vs Multi-Region tradeoffs","difficulty":"hard","question":"An insurance company must keep a copy of all policy data in a geographically separate location with an RPO of zero. Which combination achieves this?","options":{"A":"Aurora Global Database with synchronous writes to all regions","B":"RDS Multi-AZ with cross-region automated backup replication","C":"DynamoDB Global Tables — active-active with last-writer-wins replication","D":"S3 Cross-Region Replication with versioning and Object Lock"},"correct":"C","explanation":"RPO of zero requires that every acknowledged write already exists in both locations. DynamoDB Global Tables replicates writes to all regions before acknowledging, providing near-zero RPO. Aurora Global Database uses asynchronous replication (< 1 second lag) so the primary acknowledges before the secondary confirms — RPO is near-zero but technically not zero.","distractors":{"A":"Aurora Global Database replicates asynchronously to secondary regions; the primary acknowledges before secondary confirms, so RPO is not zero.","B":"Cross-region backup replication is periodic, not continuous — cannot achieve RPO of zero.","D":"S3 CRR replicates asynchronously after the primary write is acknowledged; RPO is minutes, not zero."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["rpo","dynamodb","global-tables","synchronous-replication"],"verified":true},{"id":"01-a7b8c9d0","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"easy","question":"A web application serves HTTPS traffic and requires path-based routing to send /api/* requests to one target group and all other traffic to another. Which load balancer should be used?","options":{"A":"Network Load Balancer with TCP listeners","B":"Application Load Balancer with listener rules","C":"Classic Load Balancer with sticky sessions","D":"Network Load Balancer with TLS termination"},"correct":"B","explanation":"ALB operates at Layer 7 (HTTP/HTTPS) and supports content-based routing via listener rules, including path-based conditions like /api/*. NLB operates at Layer 4 and has no concept of HTTP paths or content-based routing.","distractors":{"A":"NLB cannot inspect HTTP paths; it has no content-based routing capability.","C":"Classic Load Balancer is a legacy service that does not support path-based routing rules.","D":"NLB with TLS termination still operates at Layer 4 and cannot route based on HTTP request paths."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/application/listener-update-rules.html","tags":["alb","path-routing","layer-7"],"verified":true},{"id":"01-b8c9d0e1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"medium","question":"A gaming company needs a load balancer for UDP-based game server traffic on port 9000 with static IP addresses for player firewall whitelisting. Which load balancer meets these requirements?","options":{"A":"Application Load Balancer with a static Elastic IP","B":"Network Load Balancer with Elastic IP addresses per AZ","C":"Application Load Balancer with AWS Global Accelerator","D":"Classic Load Balancer with an Elastic IP assigned"},"correct":"B","explanation":"NLB natively supports UDP and assigns static Elastic IP addresses per Availability Zone, making it ideal when clients or firewalls must whitelist specific IPs. ALB only supports HTTP/HTTPS/gRPC; it cannot handle UDP traffic.","distractors":{"A":"ALB does not support UDP traffic; it is a Layer 7 load balancer limited to HTTP, HTTPS, and gRPC.","C":"Global Accelerator improves global routing but does not add UDP support to ALB.","D":"Classic Load Balancer does not support UDP and is a legacy service not recommended for new workloads."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/network/introduction.html","tags":["nlb","udp","static-ip","gaming"],"verified":true},{"id":"01-c9d0e1f2","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"medium","question":"A financial trading platform requires ultra-low latency TCP connections and must preserve the client source IP at the target without proxy protocol. Which load balancer satisfies this?","options":{"A":"Application Load Balancer — passes X-Forwarded-For headers with the original client IP","B":"Network Load Balancer — preserves client source IP natively for TCP traffic","C":"Application Load Balancer with connection draining disabled","D":"Classic Load Balancer with TCP mode enabled"},"correct":"B","explanation":"NLB in TCP mode preserves the client's source IP address natively at the instance level — the target sees the actual client IP in the packet without any proxy protocol. ALB terminates TCP and creates a new connection, providing the original IP only via the X-Forwarded-For HTTP header.","distractors":{"A":"X-Forwarded-For requires HTTP header parsing at the application layer and adds latency from header inspection — not true source IP preservation at the TCP level.","C":"Connection draining settings affect deregistration behavior, not source IP preservation.","D":"Classic Load Balancer in TCP mode requires proxy protocol for client IP; it does not preserve it natively like NLB."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/network/load-balancer-target-groups.html","tags":["nlb","source-ip","tcp","low-latency"],"verified":true},{"id":"01-d0e1f2a3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"hard","question":"A company runs microservices on ECS and needs to expose multiple services on the same DNS name using different ports, including HTTP REST and gRPC. TLS must terminate at the load balancer. Which configuration is correct?","options":{"A":"One ALB with multiple HTTPS listeners on different ports, each routing to a different ECS target group","B":"One NLB with TLS listeners on different ports forwarding to ECS tasks","C":"One ALB with a single HTTPS listener using host-based routing","D":"Separate ALBs for each microservice with Route 53 weighted routing"},"correct":"A","explanation":"ALB supports multiple listeners on different ports and natively handles both HTTP/1.1 (REST) and HTTP/2 (gRPC) with TLS termination. Each listener routes to a separate ECS target group. ALB's gRPC support makes it ideal for mixed protocol microservice architectures under one DNS name.","distractors":{"B":"NLB with TLS termination passes raw TCP without protocol-level routing; it cannot differentiate gRPC from REST based on content.","C":"Host-based routing differentiates by hostname, not port; services sharing the same DNS name and differing only by port need per-port listeners.","D":"Separate ALBs per microservice increases cost and complexity unnecessarily."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/application/load-balancer-listeners.html","tags":["alb","grpc","microservices","ecs","tls"],"verified":true},{"id":"01-e1f2a3b4","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"easy","question":"Which scenario is a valid reason to choose NLB over ALB?","options":{"A":"The application needs URL path-based routing","B":"The application requires WebSocket support","C":"The application must handle millions of requests per second with extreme Layer 4 throughput","D":"The application uses HTTP redirects from port 80 to 443"},"correct":"C","explanation":"NLB is designed for extreme Layer 4 performance, handling millions of requests per second with ultra-low latency. It scales automatically without warm-up. For raw TCP/UDP throughput scenarios, NLB's Layer 4 processing has lower overhead per connection than ALB.","distractors":{"A":"URL path-based routing requires Layer 7 inspection and is only supported by ALB.","B":"Both ALB and NLB support WebSocket connections; this is not a differentiator favoring NLB.","D":"HTTP-to-HTTPS redirects are a Layer 7 feature requiring ALB; NLB cannot perform HTTP redirects."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/network/introduction.html","tags":["nlb","alb","throughput","layer4"],"verified":true},{"id":"01-f2a3b4c5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ALB vs NLB: when to use each","difficulty":"medium","scenario":"A SaaS platform exposes both a customer-facing HTTPS API and an internal gRPC service used between microservices on the same EC2 fleet.","question":"Which load balancing setup minimizes cost while supporting both protocols with TLS termination?","options":{"A":"One ALB handling HTTPS and gRPC via separate target groups and listener rules","B":"Two NLBs, one for HTTPS and one for gRPC, both with TLS offload","C":"One NLB with two TCP listeners, no TLS termination at the load balancer","D":"One ALB for HTTPS and one NLB for gRPC with a shared Elastic IP"},"correct":"A","explanation":"A single ALB can handle both HTTPS (HTTP/1.1) and gRPC (HTTP/2) on the same or different ports via listener rules, with TLS termination for both. This eliminates the need for a second load balancer, reducing cost. ALB natively supports gRPC protocol detection and routes to separate target groups per service.","distractors":{"B":"Two NLBs doubles load balancer cost, and NLB does not perform content-based routing between gRPC and REST — the distinction must be made at the application level.","C":"Without TLS termination at the load balancer, each EC2 instance must manage its own TLS certificates, increasing operational burden.","D":"NLBs cannot differentiate gRPC from HTTPS at the protocol level; only ALB performs Layer 7 protocol routing."},"source_url":"https://docs.aws.amazon.com/elasticloadbalancing/latest/application/load-balancer-listeners.html","tags":["alb","grpc","https","tls","cost"],"verified":true},{"id":"01-a3b4c5d6","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"medium","question":"A web application sees a 10x traffic spike every day at 9 AM when US offices open. The ASG uses target tracking on CPU. Scale-out takes 3 minutes. Users report slowness during the spike. What is the BEST solution?","options":{"A":"Decrease the target CPU threshold from 70% to 40%","B":"Add a scheduled scaling action to increase desired capacity at 8:55 AM","C":"Switch to step scaling with more aggressive scale-out steps","D":"Enable predictive scaling and let it learn the recurring pattern"},"correct":"D","explanation":"Predictive scaling uses ML to forecast traffic from historical patterns and pre-provisions capacity before load arrives. Since the 9 AM spike is predictable and recurring, predictive scaling learns the pattern and pre-scales before the spike, eliminating the 3-minute lag. It also adapts to variations in the pattern over time.","distractors":{"A":"Lowering the CPU target causes earlier reactive scale-out, but the 3-minute provisioning delay still causes slowness during an instantaneous spike.","B":"A scheduled action works but is brittle — it fires at a fixed time regardless of whether the spike is early, late, or larger than expected.","C":"Step scaling is still reactive; it cannot eliminate the provisioning delay inherent to reactive scaling."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-predictive-scaling.html","tags":["auto-scaling","predictive-scaling","scheduled-scaling"],"verified":true},{"id":"01-b4c5d6e7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"medium","question":"An ASG launches EC2 instances that take 5 minutes to initialize (software install, warm-up). During this time ALB health checks fail and the instance is terminated before it's ready. What is the correct solution?","options":{"A":"Increase the ALB health check interval to 10 minutes","B":"Use a lifecycle hook in the EC2_INSTANCE_LAUNCHING state to hold the instance until initialization completes","C":"Increase the Auto Scaling cooldown period to 10 minutes","D":"Set the ALB target group health check threshold to 10 consecutive failures"},"correct":"B","explanation":"Lifecycle hooks pause an instance in a wait state before it joins the Auto Scaling group and becomes subject to health checks. During this pause, initialization scripts run. Once complete, the hook sends CONTINUE to let the instance proceed. This is the purpose-built mechanism for handling slow-starting instances.","distractors":{"A":"Increasing the ALB health check interval delays failure detection but does not prevent evaluation of new instances too early.","C":"Cooldown prevents new scaling actions from triggering; it does not delay the health check evaluation of already-launching instances.","D":"Requiring 10 consecutive failures adds buffer but is fragile; it also delays detection of genuinely unhealthy instances."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/lifecycle-hooks.html","tags":["auto-scaling","lifecycle-hooks","initialization","health-checks"],"verified":true},{"id":"01-c5d6e7f8","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"easy","question":"What is the purpose of the Auto Scaling cooldown period?","options":{"A":"To wait for instances to fully initialize before sending traffic","B":"To prevent Auto Scaling from launching or terminating instances before the effect of a previous scaling activity is visible in metrics","C":"To delay termination of instances that have active connections","D":"To set the minimum time an instance must run before being eligible for scale-in"},"correct":"B","explanation":"The cooldown period (default 300 seconds) pauses Auto Scaling from launching or terminating additional instances after a scaling activity. This lets new instances start handling traffic so that CloudWatch metrics stabilize before another scaling decision is made, preventing over-scaling or thrashing.","distractors":{"A":"Waiting for instances to initialize before receiving traffic is the role of ALB health check warm-up or lifecycle hooks, not cooldown.","C":"Connection draining (deregistration delay) handles gracefully draining active connections; it is separate from cooldown.","D":"Scale-in protection can be enabled per-instance but is a separate feature from the cooldown period."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-scaling-cooldowns.html","tags":["auto-scaling","cooldown","scaling-policy"],"verified":true},{"id":"01-d6e7f8a9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"hard","question":"A company runs a stateful application on an ASG. During scale-in, running jobs on terminating instances are lost; jobs take up to 10 minutes to complete. Which combination prevents job loss?","options":{"A":"Enable ALB connection draining with a 600-second timeout","B":"Use an EC2_INSTANCE_TERMINATING lifecycle hook with job draining, plus instance scale-in protection on busy instances","C":"Set a longer cooldown period of 600 seconds","D":"Use an SQS queue for jobs and scale based on queue depth"},"correct":"B","explanation":"The EC2_INSTANCE_TERMINATING lifecycle hook pauses termination so in-flight jobs can complete. Combined with instance scale-in protection on instances currently processing jobs (preventing Auto Scaling from selecting them for termination), no work is lost. The hook allows up to the configured heartbeat timeout before AWS forces termination.","distractors":{"A":"Connection draining handles ALB HTTP connections but does not affect EC2 instance termination timing initiated by Auto Scaling.","C":"Cooldown prevents new scaling actions but does not delay an already-initiated scale-in termination event.","D":"SQS-based scaling is a valid architectural pattern but does not immediately protect jobs in-flight on currently running instances."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/lifecycle-hooks.html","tags":["auto-scaling","lifecycle-hooks","scale-in","instance-protection"],"verified":true},{"id":"01-e7f8a9b0","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"medium","question":"CPU utilization spikes to 90% during brief bursts but averages 30% over 5 minutes. Target tracking at 60% triggers frequent scale-out and scale-in events ('flapping'). What is the BEST adjustment?","options":{"A":"Switch to a step scaling policy with a higher CPU threshold","B":"Increase the CloudWatch metric evaluation period and use a longer scale-in cooldown","C":"Switch to ALB request count per target instead of CPU","D":"Disable scale-in in the target tracking policy"},"correct":"B","explanation":"A longer CloudWatch evaluation period (e.g., 5-10 minute average) smooths out brief spikes so transient CPU bursts don't trigger scale-out. A longer scale-in cooldown confirms that reduced load is sustained before scaling in. Together these eliminate flapping caused by transient spikes without sacrificing responsiveness to genuine load increases.","distractors":{"A":"Step scaling reacts to instantaneous metrics and does not inherently smooth transient spikes better than target tracking with appropriate averaging.","C":"Switching metrics may help if request count correlates better with actual load, but the averaging approach directly addresses the root cause of flapping.","D":"Disabling scale-in means the cluster is never reduced, leading to perpetually over-provisioned, expensive infrastructure."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-scaling-target-tracking.html","tags":["auto-scaling","target-tracking","flapping","cooldown"],"verified":true},{"id":"01-e7f8a9b0x","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Auto Scaling groups: policies, cooldown, lifecycle hooks","difficulty":"easy","question":"An Auto Scaling group has a minimum of 2, desired of 4, and maximum of 10 instances. A scale-in event triggers. Which instance does Auto Scaling terminate by default?","options":{"A":"The instance with the highest CPU utilization","B":"The oldest instance in the group","C":"The instance in the AZ with the most instances, then the one closest to the next billing hour","D":"A randomly selected instance"},"correct":"C","explanation":"Auto Scaling's default termination policy first selects the AZ with the most instances to maintain balance, then within that AZ selects the instance closest to the next billing hour to maximize usage of already-paid compute time. This behavior can be overridden with custom termination policies.","distractors":{"A":"Auto Scaling does not use CloudWatch CPU metrics to select which instance to terminate; it uses the termination policy.","B":"The oldest launch configuration/template is part of one termination policy option, but it is not the default behavior.","D":"Selection is deterministic based on the termination policy, not random."},"source_url":"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-instance-termination.html","tags":["auto-scaling","termination-policy","scale-in"],"verified":true},{"id":"01-f8a9b0c1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Route 53 routing policies: failover, latency, weighted, geolocation","difficulty":"easy","question":"A company has a primary website in us-east-1 and a static S3-hosted maintenance page. If the primary fails its health check, users should automatically see the maintenance page. Which Route 53 routing policy implements this?","options":{"A":"Weighted routing with 90% to primary and 10% to S3","B":"Failover routing with the primary record active and S3 as the secondary","C":"Latency-based routing between the ALB and S3","D":"Geolocation routing with a default record pointing to S3"},"correct":"B","explanation":"Route 53 failover routing has a primary record (with health check) and a secondary that only receives traffic when the primary health check fails. When the ALB endpoint fails, Route 53 automatically resolves to the S3 static site. No manual intervention is required.","distractors":{"A":"Weighted routing distributes traffic proportionally at all times; it does not redirect all traffic to secondary on primary failure.","C":"Latency-based routing selects the lowest-latency endpoint; it does not implement active/passive failover based on health.","D":"Geolocation routing selects endpoints based on geographic origin, not health check state."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-failover.html","tags":["route53","failover-routing","health-checks"],"verified":true},{"id":"01-a9b0c1d2","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Route 53 routing policies: failover, latency, weighted, geolocation","difficulty":"medium","question":"A SaaS company is gradually migrating users from a legacy system to a new version. They want 10% of traffic on the new version initially, with instant rollback capability. Which Route 53 policy supports this?","options":{"A":"Failover routing — set the new version as secondary","B":"Weighted routing — assign weights of 10 and 90 to new and old records respectively","C":"Latency-based routing between old and new versions","D":"Multivalue answer routing returning both endpoints"},"correct":"B","explanation":"Weighted routing assigns numeric weights to records and Route 53 routes traffic proportionally. Setting new=10 and old=90 sends 10% to the new version. Increasing the new weight or setting it to 0 for rollback takes effect at DNS TTL expiry — no infrastructure changes required.","distractors":{"A":"Failover routing is binary — all traffic goes to primary unless it fails; it does not support gradual traffic shifting.","C":"Latency-based routing selects by network latency, not by a controlled percentage split.","D":"Multivalue answer returns multiple IPs for client-side load balancing; it does not provide controlled percentage splitting."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-weighted.html","tags":["route53","weighted-routing","canary","blue-green"],"verified":true},{"id":"01-b0c1d2e3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Route 53 routing policies: failover, latency, weighted, geolocation","difficulty":"medium","question":"A video streaming company deploys servers in us-east-1, eu-west-1, and ap-southeast-1. Users should always be routed to the nearest AWS region for lowest latency. Which Route 53 policy achieves this?","options":{"A":"Geolocation routing with records for North America, Europe, and Asia","B":"Latency-based routing with records for each region","C":"Weighted routing with equal weights across all three regions","D":"Failover routing with us-east-1 as primary"},"correct":"B","explanation":"Latency-based routing measures actual network latency from the user's DNS resolver to each region and routes to the lowest-latency region. This is more accurate than geolocation, which uses geographic boundaries that may not reflect actual network conditions.","distractors":{"A":"Geolocation routes by country/continent boundaries, not network latency; a user in Eastern Europe might have lower latency to us-east-1 but geolocation always routes to the European record.","C":"Equal weights distribute traffic evenly regardless of user location, resulting in high latency for many users.","D":"Failover routing sends all traffic to the primary region unless it fails; it does not optimize by user proximity."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-latency.html","tags":["route53","latency-routing","global-distribution"],"verified":true},{"id":"01-c1d2e3f4","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Route 53 routing policies: failover, latency, weighted, geolocation","difficulty":"hard","question":"A healthcare company must route European users to EU servers for GDPR compliance regardless of latency. Users from unconfigured countries should hit a US default server. Which Route 53 configuration achieves this?","options":{"A":"Latency-based routing with eu-west-1 and us-east-1 records","B":"Geolocation routing with continent records for Europe and a Default record for us-east-1","C":"Weighted routing with higher weights for European countries","D":"Geoproximity routing with a large bias toward eu-west-1"},"correct":"B","explanation":"Geolocation routing can be configured with records for specific countries or continents (Europe) and a Default record that catches all unmatched locations. This guarantees European users always hit EU servers for GDPR compliance. The Default record in geolocation routing is specifically designed for this fallback pattern.","distractors":{"A":"Latency-based routing routes by measured network performance; a European user might hit the US server if latency is lower, violating GDPR data residency requirements.","C":"Weighted routing distributes traffic proportionally regardless of user location; it cannot enforce geographic routing boundaries.","D":"Geoproximity routing shifts traffic using a bias but still routes some users outside their target region depending on bias value; it does not enforce strict geographic boundaries."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-geo.html","tags":["route53","geolocation-routing","gdpr","compliance"],"verified":true},{"id":"01-d2e3f4a5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Route 53 routing policies: failover, latency, weighted, geolocation","difficulty":"medium","question":"Route 53 failover health checks are triggering unnecessary failovers every 30 seconds due to brief network blips. What adjustment reduces false failovers?","options":{"A":"Increase the health check request interval from 30 to 10 seconds","B":"Increase the failure threshold so more consecutive failures are required before marking unhealthy","C":"Switch from HTTP health checks to TCP health checks","D":"Enable latency-based routing in addition to failover routing"},"correct":"B","explanation":"The Route 53 health check failure threshold sets how many consecutive failed checks are required before marking an endpoint unhealthy. Increasing from the default 3 to a higher value (e.g., 5) means transient failures must persist through more check cycles before triggering failover, filtering out brief network blips while still detecting genuine outages.","distractors":{"A":"Decreasing the request interval (30 → 10 seconds) means more frequent checks, making the system MORE sensitive to brief failures — the opposite of what's needed.","C":"Switching to TCP checks does not affect the threshold behavior; TCP checks can also fail transiently.","D":"Adding latency-based routing does not affect health check evaluation or failover threshold logic."},"source_url":"https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/health-checks-creating-values.html","tags":["route53","health-checks","failover","threshold"],"verified":true},{"id":"01-e3f4a5b6","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"RDS Multi-AZ vs Read Replicas","difficulty":"easy","question":"A development team wants to offload reporting queries from their production RDS MySQL database without impacting production performance. Which feature addresses this?","options":{"A":"RDS Multi-AZ — queries the standby instance directly","B":"RDS Read Replica — point reporting tools at one or more replicas","C":"RDS automated backups — restore a copy for reporting","D":"RDS Multi-AZ — enable read access on the standby endpoint"},"correct":"B","explanation":"RDS Read Replicas receive asynchronous replication from the primary and can serve SELECT queries, offloading read traffic from production. You can create up to 15 read replicas for MySQL/MariaDB and Aurora. The Multi-AZ standby is not queryable — it exists solely for automatic failover.","distractors":{"A":"The Multi-AZ standby instance is not accessible for queries; it is a hot standby that cannot serve read traffic.","C":"Restoring from automated backups creates a point-in-time snapshot copy, not a live replica; used for recovery, not ongoing reporting.","D":"The Multi-AZ standby cannot be configured for read access; this capability does not exist in standard RDS Multi-AZ."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_ReadRepl.html","tags":["rds","read-replica","multi-az","reporting"],"verified":true},{"id":"01-f4a5b6c7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"RDS Multi-AZ vs Read Replicas","difficulty":"medium","question":"An RDS MySQL database with Multi-AZ suffers a primary instance failure. What happens automatically, and what does NOT happen automatically?","options":{"A":"Automatic failover occurs; the application must update its connection string","B":"Automatic failover occurs; the RDS DNS endpoint automatically resolves to the new primary — no application change needed","C":"The read replica is automatically promoted; the application endpoint updates","D":"A new primary is launched from the most recent backup; takes 20-30 minutes"},"correct":"B","explanation":"RDS Multi-AZ automatically detects primary failure and promotes the standby within 1-2 minutes. The RDS endpoint DNS CNAME updates to resolve to the new primary's IP. Applications using the RDS endpoint — not a hardcoded IP — reconnect automatically after the DNS TTL expires without any configuration change.","distractors":{"A":"Applications do not need to update connection strings; the DNS endpoint stays the same and resolves to the new primary after failover.","C":"Read replicas are not involved in Multi-AZ failover; the standby (distinct from read replicas) is promoted.","D":"Multi-AZ failover does not involve restoring from backup; the hot standby already has current data and promotion takes 1-2 minutes."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.MultiAZ.html","tags":["rds","multi-az","failover","dns","automatic"],"verified":true},{"id":"01-a5b6c7d8","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"RDS Multi-AZ vs Read Replicas","difficulty":"hard","question":"A company has RDS PostgreSQL with Multi-AZ and three read replicas. Compliance mandates surviving a full region failure with the lowest recovery time. Which additional configuration satisfies this?","options":{"A":"Create a cross-region read replica with automated promotion scripts via CloudWatch alarms","B":"Enable cross-region automated backup replication and restore on failure","C":"Migrate to Aurora PostgreSQL with Aurora Global Database and a secondary region","D":"Use AWS DMS to continuously replicate to an RDS instance in a second region"},"correct":"C","explanation":"Aurora Global Database provides managed cross-region replication with < 1 second lag and enables promotion of a secondary region to primary in under a minute via a single API call. This gives the lowest RTO. Standard RDS cross-region read replicas require manual promotion steps and have higher lag. Aurora Global Database is the purpose-built managed solution.","distractors":{"A":"Cross-region RDS read replicas require manual promotion and repointing applications; RTO is higher than Aurora Global Database.","B":"Cross-region backup restoration requires launching a new DB instance from a snapshot, taking 20-60+ minutes — a cold standby with poor RTO.","D":"DMS continuous replication adds operational complexity and typically higher latency vs. Aurora Global Database; no managed failover."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database.html","tags":["rds","aurora","global-database","cross-region","disaster-recovery"],"verified":true},{"id":"01-b6c7d8e9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"RDS Multi-AZ vs Read Replicas","difficulty":"medium","question":"An RDS read replica is significantly lagging behind the primary due to a write-heavy workload. What is the most direct fix?","options":{"A":"Upgrade the read replica to a larger instance class with more CPU and faster gp3 storage","B":"Enable Multi-AZ on the read replica","C":"Create additional read replicas to distribute replication load","D":"Enable minor version auto-upgrades on the primary"},"correct":"A","explanation":"Read replica lag is caused by the replica's inability to apply incoming write changes fast enough. A larger instance class provides more CPU to process the replication stream and faster I/O (gp3 or io2 storage) to keep up with write-intensive workloads. This directly addresses the compute and I/O bottleneck causing lag.","distractors":{"B":"Enabling Multi-AZ on a read replica creates a standby for the replica's own HA but does not reduce replication lag between primary and replica.","C":"Adding more replicas distributes read query load but each replica independently applies all writes from the primary; lag on existing replicas is not reduced.","D":"Minor version upgrades may include performance improvements but are not a targeted solution for replication lag from a write-heavy workload."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_ReadRepl.html","tags":["rds","read-replica","replication-lag","instance-class"],"verified":true},{"id":"01-c7d8e9f0","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"RDS Multi-AZ vs Read Replicas","difficulty":"easy","question":"Which statement about RDS Multi-AZ is TRUE?","options":{"A":"Multi-AZ provides a read endpoint on the standby to improve read performance","B":"Multi-AZ uses synchronous replication to a standby in a different AZ for automatic failover","C":"Multi-AZ is available only for RDS MySQL and PostgreSQL","D":"Multi-AZ standby instances can serve as read replicas to reduce costs"},"correct":"B","explanation":"RDS Multi-AZ uses synchronous block-level replication to a standby in a different AZ. Synchronous means every write is committed to the standby before being acknowledged to the application, ensuring zero data loss on failover. The standby is not accessible for reads.","distractors":{"A":"The Multi-AZ standby has no read endpoint; it is invisible to applications and exists solely as an automatic failover target.","C":"Multi-AZ is available for all RDS engines including MySQL, PostgreSQL, MariaDB, Oracle, and SQL Server.","D":"The standby cannot serve as a read replica; read replicas are separate instances with their own endpoints using asynchronous replication."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.MultiAZ.html","tags":["rds","multi-az","synchronous-replication"],"verified":true},{"id":"01-d8e9f0a1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Aurora Global Database","difficulty":"medium","question":"A company adds an Aurora Global Database secondary region in eu-west-1 to a primary in us-east-1. What read/write capabilities does each region have in normal operations?","options":{"A":"Both regions accept writes; reads can be served from either","B":"Only us-east-1 accepts writes; eu-west-1 serves reads from its local replicas","C":"eu-west-1 accepts writes that are forwarded to us-east-1; reads are served locally","D":"Both regions replicate bidirectionally with conflict resolution"},"correct":"B","explanation":"Aurora Global Database has one primary region that accepts all writes. Secondary regions receive replication (< 1 second lag) and serve read traffic from local replica instances, reducing read latency for users in those regions. Secondary regions cannot accept writes unless promoted during a failover.","distractors":{"A":"Aurora Global Database is not active-active for writes; only the primary region writes. DynamoDB Global Tables supports active-active writes.","C":"Writes are not forwarded from secondary to primary; the secondary is read-only.","D":"Aurora Global Database uses one-directional replication from primary to secondaries, not bidirectional with conflict resolution."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database.html","tags":["aurora","global-database","multi-region","read-write"],"verified":true},{"id":"01-e9f0a1b2","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Aurora Global Database","difficulty":"hard","question":"An Aurora Global Database primary region becomes completely unavailable. What is the correct sequence of steps to restore write capability in the secondary region?","options":{"A":"Create a new Aurora cluster in the secondary region and restore from the most recent backup","B":"Detach the secondary cluster from the Global Database to promote it to a standalone cluster, then update application endpoints","C":"Delete the Global Database and create a new primary in the secondary region","D":"Enable Multi-AZ on the secondary cluster to allow writes"},"correct":"B","explanation":"To promote a secondary Aurora Global Database region, you detach it (using the Remove from Global Database or Promote action) to convert it to a standalone Aurora cluster with full read/write capability, completing in under a minute. Application endpoints must then be updated to point to the promoted cluster.","distractors":{"A":"Restoring from backup creates a new instance with potential data loss and takes significantly longer than promoting the existing secondary, which already has near-real-time data.","C":"Deleting the Global Database is destructive and unnecessary; the secondary cluster is already running and current — it just needs promotion.","D":"Multi-AZ on the secondary provides HA within that region but does not grant write capability to a Global Database secondary."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database-disaster-recovery.html","tags":["aurora","global-database","failover","promotion"],"verified":true},{"id":"01-f0a1b2c3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Aurora Global Database","difficulty":"easy","question":"What is the typical replication lag between Aurora Global Database primary and secondary regions?","options":{"A":"Less than 1 second","B":"1-5 seconds","C":"5-10 seconds","D":"Depends entirely on the size of each transaction"},"correct":"A","explanation":"Aurora Global Database replicates at the storage layer rather than the database layer, achieving typical cross-region replication lag under 1 second. This sub-second lag enables near-zero RPO for cross-region disaster recovery and allows secondary regions to serve reads with acceptably fresh data.","distractors":{"B":"1-5 seconds is typical for some other cross-region mechanisms; Aurora Global Database targets under 1 second.","C":"5-10 seconds would be unacceptably high for Aurora Global Database's design goals.","D":"While large transactions may take fractionally longer, the storage-layer architecture maintains under 1 second lag under normal conditions."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database.html","tags":["aurora","global-database","replication-lag"],"verified":true},{"id":"01-a1c3e5g7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"Aurora Global Database","difficulty":"medium","question":"How many secondary regions can an Aurora Global Database have?","options":{"A":"1","B":"3","C":"5","D":"Unlimited"},"correct":"C","explanation":"Aurora Global Database supports up to 5 secondary read-only regions in addition to the primary region, for a total of 6 regions. Each secondary region can have up to 16 read replica instances. This enables globally distributed low-latency reads while maintaining a single write endpoint.","distractors":{"A":"One secondary region is the minimum useful configuration but not the maximum.","B":"Three is not the correct limit; Aurora Global Database supports up to 5.","D":"There is a defined limit of 5 secondary regions per Global Database."},"source_url":"https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/aurora-global-database.html","tags":["aurora","global-database","limits","secondary-regions"],"verified":true},{"id":"01-b3d5f7h9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"S3 versioning and cross-region replication","difficulty":"easy","question":"A developer accidentally deletes a critical S3 object. With S3 versioning enabled, what happens when you delete an object without specifying a version ID?","options":{"A":"The object and all its versions are permanently deleted","B":"A delete marker is inserted; all previous versions are preserved and recoverable","C":"The most recent version is permanently deleted; older versions remain","D":"The deletion is rejected; versioning prevents deletion"},"correct":"B","explanation":"When you delete an S3 versioned object without a version ID, S3 inserts a delete marker as the current version. The object appears deleted via standard API but all previous versions remain intact. To restore, delete the delete marker — making the most recent non-marker version current again.","distractors":{"A":"Deleting without a version ID only adds a delete marker; all actual data versions are preserved. To permanently delete a version, you must specify the version ID.","C":"The operation adds a delete marker — it does not permanently delete any version of the object.","D":"Versioning does not prevent deletion; it enables recovery after accidental deletion."},"source_url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/DeletingObjectVersions.html","tags":["s3","versioning","delete-marker","recovery"],"verified":true},{"id":"01-c5e7g9i1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"S3 versioning and cross-region replication","difficulty":"medium","question":"A company wants to replicate all objects — including existing ones — from an S3 bucket in us-east-1 to a bucket in us-west-2 for disaster recovery. Which configuration is required?","options":{"A":"Enable Cross-Region Replication (CRR); existing objects are replicated automatically","B":"Enable CRR on the source bucket; use S3 Batch Operations to replicate existing objects separately","C":"Enable S3 Transfer Acceleration on the destination and configure lifecycle rules","D":"Use AWS DataSync for a recurring sync job between the two buckets"},"correct":"B","explanation":"S3 CRR only replicates objects created or modified AFTER replication is enabled; existing objects are not replicated automatically. To replicate existing objects, use S3 Batch Operations with the S3 Replication operation. Both steps together achieve complete bucket replication.","distractors":{"A":"CRR does not backfill existing objects; only objects uploaded or modified after enabling CRR are replicated — a common misconception.","C":"Transfer Acceleration accelerates uploads from external clients; it does not perform bucket-to-bucket replication. Lifecycle rules manage object transitions, not cross-region copying.","D":"DataSync is designed for bulk one-time or periodic transfers, not continuous real-time replication; CRR is the native solution for ongoing cross-region replication."},"source_url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/replication-what-is-isnot-replicated.html","tags":["s3","crr","batch-operations","existing-objects"],"verified":true},{"id":"01-d7f9h1j3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"S3 versioning and cross-region replication","difficulty":"medium","question":"A financial firm requires that compliance documents in S3 cannot be deleted or overwritten for 7 years, even by the root account. Which feature enforces this?","options":{"A":"S3 versioning with MFA Delete enabled","B":"S3 Object Lock in Compliance mode with a 7-year retention period","C":"S3 bucket policy denying DeleteObject for all principals","D":"S3 Object Lock in Governance mode with a 7-year retention period"},"correct":"B","explanation":"S3 Object Lock in Compliance mode prevents any user — including root — from deleting or overwriting objects for the retention period. The mode cannot be changed and the retention period cannot be shortened. This is the WORM (Write Once Read Many) solution for strict regulatory compliance.","distractors":{"A":"MFA Delete requires MFA to delete versions or change versioning state, but can be disabled by root and does not enforce a time-based retention period.","C":"A bucket policy denying DeleteObject can be modified or removed by a sufficiently privileged administrator; it is not immutable.","D":"Governance mode allows users with the s3:BypassGovernanceRetention permission to override retention settings; only Compliance mode is truly immutable."},"source_url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock-overview.html","tags":["s3","object-lock","compliance-mode","worm","retention"],"verified":true},{"id":"01-e9g1i3k5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"S3 versioning and cross-region replication","difficulty":"hard","question":"S3 Cross-Region Replication is configured from bucket A (us-east-1) to bucket B (eu-west-1). A developer deletes an object in bucket A. What happens in bucket B by default?","options":{"A":"The object is deleted from bucket B immediately","B":"By default, delete markers are NOT replicated; the object remains in bucket B unless delete marker replication is explicitly enabled","C":"The object is moved to the S3 Recycle Bin in bucket B","D":"CRR automatically adds a delete marker to bucket B within 15 minutes"},"correct":"B","explanation":"By default, S3 CRR does not replicate delete markers. This is a deliberate design to protect against accidental or malicious deletions propagating to the replica. Delete marker replication must be explicitly enabled in the replication rule. Without it, the object persists in the destination bucket.","distractors":{"A":"Deletes are not automatically replicated by CRR unless delete marker replication is explicitly configured.","C":"S3 Recycle Bin is a separate feature for recovering recently deleted objects; it is not involved in CRR delete behavior.","D":"Delete markers are not replicated by default; they must be explicitly enabled."},"source_url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/delete-marker-replication.html","tags":["s3","crr","delete-markers"],"verified":true},{"id":"01-f1h3j5l7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"S3 versioning and cross-region replication","difficulty":"easy","question":"What must be enabled on BOTH source and destination S3 buckets before Cross-Region Replication can be configured?","options":{"A":"S3 Transfer Acceleration","B":"S3 Versioning","C":"Server-side encryption with KMS","D":"S3 Intelligent-Tiering"},"correct":"B","explanation":"S3 versioning must be enabled on both source and destination buckets as a prerequisite for CRR. Versioning allows objects to be tracked and replicated without data loss and ensures delete markers and version histories are managed correctly. CRR cannot be configured on an unversioned bucket.","distractors":{"A":"Transfer Acceleration accelerates uploads from external clients and is not a prerequisite for CRR.","C":"SSE-KMS encryption is supported in CRR with appropriate key policies but is not a prerequisite.","D":"S3 Intelligent-Tiering is a storage class, not a prerequisite for CRR."},"source_url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/replication-prereqs.html","tags":["s3","crr","versioning","prerequisites"],"verified":true},{"id":"01-a3c5e7g9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"easy","question":"An order processing web frontend must remain responsive even when the downstream fulfillment service is slow. Which AWS service decouples the frontend from the fulfillment service?","options":{"A":"Amazon SQS — the frontend enqueues orders; fulfillment processes them at its own pace","B":"Amazon SNS — the frontend publishes order events to all subscribers simultaneously","C":"Amazon EventBridge — the frontend emits events triggering fulfillment Lambda functions","D":"Amazon ElastiCache — cache order data so the frontend doesn't wait for fulfillment"},"correct":"A","explanation":"SQS is a durable message queue that decouples producers from consumers. The frontend writes orders to the queue and immediately returns success to the user. The fulfillment service reads from the queue independently, absorbing pace differences. This is the classic producer-consumer decoupling pattern.","distractors":{"B":"SNS is a pub/sub service that pushes messages in real time; it does not buffer messages to absorb pace differences.","C":"EventBridge is an event bus; while it decouples services, it does not buffer messages for rate leveling like SQS.","D":"ElastiCache is a caching service; caching order data does not solve the fundamental problem of the frontend waiting for fulfillment."},"source_url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/welcome.html","tags":["sqs","decoupling","queue","producer-consumer"],"verified":true},{"id":"01-b5d7f9h1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"medium","question":"A single order event must be delivered independently to inventory, billing, and shipping services simultaneously. Each service needs its own copy. Which pattern achieves this?","options":{"A":"Single SQS queue with all three services polling from it","B":"SNS topic with three SQS queues subscribed — fan-out pattern","C":"SNS topic with three Lambda functions subscribed directly","D":"SQS FIFO queue with message group IDs per destination service"},"correct":"B","explanation":"The SNS fan-out pattern publishes one message to an SNS topic, which delivers a copy to each subscribed SQS queue. Each service has its own queue and processes messages independently. SQS queues provide durability and buffering, so if a service is temporarily unavailable, messages are held in its queue until recovery.","distractors":{"A":"A single SQS queue means only one consumer receives each message; all three services compete for the same messages rather than each receiving all messages.","C":"Direct Lambda subscriptions to SNS work but Lambda failures may lose messages with limited retry flexibility; SQS queues provide better durability.","D":"SQS FIFO message groups handle ordering within a group; they don't solve fan-out — all three services would still share one queue."},"source_url":"https://docs.aws.amazon.com/sns/latest/dg/sns-sqs-as-subscriber.html","tags":["sns","sqs","fan-out","pub-sub"],"verified":true},{"id":"01-c7e9g1i3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"medium","question":"Malformed payment messages cause the processing Lambda to fail after all retries, repeatedly blocking the SQS queue. What is the correct solution?","options":{"A":"Increase the Lambda timeout so malformed messages eventually succeed","B":"Configure a Dead Letter Queue (DLQ) to capture messages exceeding the maximum receive count","C":"Enable SQS long polling to give Lambda more time on difficult messages","D":"Switch to SQS FIFO to prevent out-of-order processing"},"correct":"B","explanation":"A Dead Letter Queue captures messages that fail after a configurable number of receive attempts (maxReceiveCount). Poison messages are moved to the DLQ for inspection and remediation instead of repeatedly failing and blocking the main queue. This keeps the pipeline healthy.","distractors":{"A":"Increasing timeout helps slow-running code but not malformed messages that fail immediately regardless of timeout.","C":"Long polling reduces empty receives; it has no effect on messages that fail processing.","D":"FIFO queues provide ordering and exactly-once delivery, but malformed messages would still block the queue head; a DLQ is still required."},"source_url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html","tags":["sqs","dead-letter-queue","dlq","error-handling"],"verified":true},{"id":"01-d9f1h3j5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"hard","question":"Each order must be processed exactly once, and orders from the same customer must be processed in the order they were placed. Which SQS configuration achieves this?","options":{"A":"Standard SQS queue with application-level deduplication","B":"SQS FIFO queue with MessageGroupId set to customer ID and MessageDeduplicationId set to order ID","C":"Standard SQS queue with visibility timeout set to maximum processing time","D":"SQS FIFO queue with a single MessageGroupId for all messages"},"correct":"B","explanation":"SQS FIFO queues provide exactly-once processing (MessageDeduplicationId deduplicates within a 5-minute window) and ordered delivery per group. Setting MessageGroupId to customer ID ensures all orders from the same customer are processed in sequence, while different customers are processed in parallel across groups.","distractors":{"A":"Standard queues provide at-least-once delivery (not exactly-once) and do not guarantee ordering; application-level deduplication cannot fully compensate.","C":"Visibility timeout prevents concurrent processing of the same message but does not enforce ordering or exactly-once delivery.","D":"A single MessageGroupId serializes all order processing regardless of customer, eliminating parallelism and creating a bottleneck."},"source_url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/FIFO-queues.html","tags":["sqs","fifo","exactly-once","ordering","message-group"],"verified":true},{"id":"01-e1g3i5k7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"medium","question":"A notification service must send the same alert to mobile push (APNs, FCM), email, and SMS simultaneously. New channels may be added in the future. Which architecture is most extensible?","options":{"A":"Lambda function that directly calls APNs, SES, and SNS SMS APIs for each alert","B":"SNS topic with subscriptions for mobile push, email, and SMS; add new subscriptions as needed","C":"SQS queue with separate Lambda consumers polling for each channel","D":"EventBridge rule triggering separate Lambdas for each channel"},"correct":"B","explanation":"SNS natively integrates with mobile push (via platform applications), email, and SMS. One publish delivers to all subscribers simultaneously. Adding a new channel only requires adding a new subscription — no publisher code changes required. This is the most extensible fan-out architecture for notifications.","distractors":{"A":"A Lambda calling each delivery API is tightly coupled; adding a channel requires modifying and redeploying the function.","C":"SQS with separate consumers requires separate queues or filtering and does not natively integrate with push notification services.","D":"EventBridge with separate Lambdas works but is more complex to maintain than SNS native integrations for notification delivery."},"source_url":"https://docs.aws.amazon.com/sns/latest/dg/welcome.html","tags":["sns","notifications","fan-out","mobile-push","extensibility"],"verified":true},{"id":"01-f3h5j7l9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"SQS and SNS for decoupled architectures","difficulty":"easy","question":"What is the maximum message retention period for an Amazon SQS queue?","options":{"A":"24 hours","B":"7 days","C":"14 days","D":"30 days"},"correct":"C","explanation":"SQS retains messages for a configurable period between 1 minute and 14 days, with a default of 4 days. Messages not consumed and deleted within the retention period are automatically removed by SQS.","distractors":{"A":"24 hours is not the maximum; 14 days is the maximum SQS retention period.","B":"7 days is not the SQS maximum; the default is 4 days with a maximum of 14 days.","D":"30 days exceeds the SQS maximum retention period of 14 days."},"source_url":"https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-message-lifecycle.html","tags":["sqs","message-retention","limits"],"verified":true},{"id":"01-a5c7e9g1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"medium","question":"User session data is stored in ElastiCache. Sessions must persist if a cache node fails and the solution must support automatic failover. Which configuration meets these requirements?","options":{"A":"ElastiCache for Memcached with 3 nodes","B":"ElastiCache for Redis with Multi-AZ enabled and automatic failover","C":"ElastiCache for Memcached with auto-discovery enabled","D":"ElastiCache for Redis cluster mode with no replicas"},"correct":"B","explanation":"ElastiCache for Redis supports persistence, replication, and automatic failover. With Multi-AZ and a replica in a different AZ, if the primary fails, ElastiCache promotes the replica automatically. Session data persists because Redis supports RDB/AOF persistence. Memcached has no replication or persistence.","distractors":{"A":"Memcached does not support replication; a node failure loses all data on that node.","C":"Auto-discovery helps applications find Memcached nodes dynamically but does not protect against data loss when a node fails.","D":"Redis cluster mode without replicas has no replication; a node failure in the cluster loses all keys in that shard."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/AutoFailover.html","tags":["elasticache","redis","multi-az","sessions","failover"],"verified":true},{"id":"01-b7d9f1h3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"medium","question":"A gaming leaderboard requires fast sorted set operations across tens of millions of entries and must survive node failures without data loss. Which ElastiCache configuration is correct?","options":{"A":"Memcached — lower latency for simple get/set operations","B":"Redis with Multi-AZ and replica nodes — natively supports sorted sets with automatic failover","C":"Memcached with consistent hashing to distribute leaderboard entries","D":"Redis with TTL set on all leaderboard entries to manage memory"},"correct":"B","explanation":"Redis natively supports sorted sets (ZSET), perfect for leaderboards — add scores, rank members, and retrieve top-N with O(log N) operations. Multi-AZ with replicas and automatic failover ensures data persists through node failures. Memcached only supports simple key-value operations.","distractors":{"A":"Memcached lacks sorted sets or complex data structures; a leaderboard in Memcached requires application-level management, losing O(log N) efficiency.","C":"Consistent hashing distributes simple cache entries; Memcached still lacks sorted set operations and a node failure loses data on that node.","D":"TTLs on leaderboard entries cause players to disappear from rankings after expiry, which is incorrect behavior for a persistent leaderboard."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/WhatIs.html","tags":["elasticache","redis","sorted-sets","leaderboard","multi-az"],"verified":true},{"id":"01-c9e1g3i5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"easy","question":"Which capability is available in ElastiCache for Redis but NOT in ElastiCache for Memcached?","options":{"A":"Sub-millisecond latency","B":"Horizontal scaling by adding nodes","C":"Pub/Sub messaging and Lua scripting","D":"In-memory key-value storage"},"correct":"C","explanation":"Redis supports Pub/Sub messaging patterns and server-side Lua scripting for atomic operations. Redis also supports complex data structures (lists, sets, sorted sets, hashes, streams), persistence, replication, and transactions — none of which are available in Memcached.","distractors":{"A":"Both Redis and Memcached provide sub-millisecond latency; this is a shared characteristic.","B":"Both engines support horizontal scaling; Memcached partitions across nodes, Redis supports sharding in cluster mode.","D":"Both engines store data in-memory; this is the fundamental property of both products."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/WhatIs.html","tags":["elasticache","redis","memcached","pub-sub"],"verified":true},{"id":"01-d1f3h5j7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"hard","question":"ElastiCache Redis cluster mode is enabled with 3 shards and 2 replicas each. One primary shard fails. What is the impact?","options":{"A":"All reads and writes fail until the primary is manually restored","B":"Keys in the failed shard are unavailable during automatic failover (60-120 seconds); other shards operate normally","C":"The entire cluster fails because cluster mode requires all shards to be available","D":"Reads continue from replicas; writes to the failed shard fail permanently until a new primary is created"},"correct":"B","explanation":"In Redis cluster mode, data is partitioned across shards via hash slots. When a primary shard fails, ElastiCache automatically promotes one of its replicas to primary, typically within 60-120 seconds. During this window, keys in that shard are unavailable. Other shards continue operating normally because each shard is independent.","distractors":{"A":"Manual restoration is not required; ElastiCache Redis with replicas automatically promotes a replica to primary.","C":"Redis cluster mode does not require all shards to be healthy; each shard operates independently and a failure affects only that portion of the keyspace.","D":"During the failover window, both reads and writes to the failed shard are unavailable; once the replica is promoted, both resume — it is not permanent."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/Replication.Redis-RedisCluster.html","tags":["elasticache","redis","cluster-mode","sharding","failover"],"verified":true},{"id":"01-e3g5i7k9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"medium","question":"A caching layer must scale horizontally across multiple threads with the largest possible cache cluster. Data is purely transient with no persistence requirement. Which ElastiCache engine is most appropriate?","options":{"A":"Redis — cluster mode provides horizontal scaling","B":"Memcached — multi-threaded architecture, scales to 40 nodes per cluster","C":"Redis — better memory efficiency for simple string caching","D":"Memcached — supports AOF persistence for durability"},"correct":"B","explanation":"Memcached is inherently multi-threaded and uses multiple CPU cores efficiently, giving maximum throughput for simple get/set operations. Memcached clusters scale to 40 nodes. Since persistence is not required, Memcached's simplicity and multi-threading are advantages over Redis for this use case.","distractors":{"A":"Redis is primarily single-threaded for command execution; Memcached's true multi-threading gives a throughput advantage for simple operations at scale.","C":"Redis actually uses more memory than Memcached for equivalent simple string data due to its more complex data structures.","D":"Memcached has no persistence capabilities (no AOF or snapshots); this statement is false."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/mem-ug/WhatIs.html","tags":["elasticache","memcached","multi-threaded","horizontal-scaling"],"verified":true},{"id":"01-f5h7j9l1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"ElastiCache Redis vs Memcached: HA patterns","difficulty":"easy","question":"Which ElastiCache engine supports in-cluster replication and automatic failover?","options":{"A":"Only Memcached","B":"Only Redis","C":"Both Redis and Memcached","D":"Neither — replication requires two separate ElastiCache clusters"},"correct":"B","explanation":"Only ElastiCache for Redis supports replication groups, replica nodes, and automatic failover with Multi-AZ. Memcached partitions data across nodes but does not replicate data between nodes — a node failure causes data loss for that partition. Redis replication ensures durability and enables automatic promotion on primary failure.","distractors":{"A":"Memcached does not support replication; only Redis has these capabilities.","C":"Memcached does not support in-cluster replication or automatic failover.","D":"Redis natively supports replication within a single replication group; separate clusters are not required."},"source_url":"https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/Replication.html","tags":["elasticache","redis","replication","failover"],"verified":true},{"id":"01-a7b9c1e3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"DynamoDB Global Tables","difficulty":"easy","question":"A company wants a DynamoDB table that accepts writes in both us-east-1 and eu-west-1 simultaneously with automatic synchronization. Which feature enables this?","options":{"A":"DynamoDB Streams with Lambda replication","B":"DynamoDB Global Tables","C":"DynamoDB Cross-Region Read Replicas","D":"AWS DataSync for cross-region sync"},"correct":"B","explanation":"DynamoDB Global Tables provides active-active multi-region replication, allowing writes in all configured regions. Changes automatically propagate to all regions within ~1 second. This enables low-latency reads and writes globally without custom replication code.","distractors":{"A":"DynamoDB Streams with Lambda is the underlying mechanism Global Tables uses; implementing it manually is complex and error-prone.","C":"DynamoDB does not have 'Cross-Region Read Replicas' as a separate feature; this is Aurora terminology.","D":"DataSync is for bulk data migration, not real-time database replication."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["dynamodb","global-tables","active-active","multi-region"],"verified":true},{"id":"01-b9c1e3g5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"DynamoDB Global Tables","difficulty":"medium","question":"A developer writes to a DynamoDB Global Table in us-east-1 and immediately reads the same item from eu-west-1 before replication completes. What guarantees the latest write is visible?","options":{"A":"Strongly consistent reads in eu-west-1","B":"No eu-west-1 read option guarantees seeing the us-east-1 write before replication completes","C":"Eventually consistent reads with a retry loop","D":"Transactional reads in eu-west-1"},"correct":"B","explanation":"DynamoDB Global Tables uses asynchronous replication. Strongly consistent reads in eu-west-1 are consistent within eu-west-1's storage but do not account for cross-region replication lag. To always see the latest write, the application must read from the same region it wrote to.","distractors":{"A":"Strongly consistent reads in eu-west-1 are within-region consistent but do not wait for cross-region replication; the item may still be the old version.","C":"Eventually consistent reads return the replicated value once replication completes, but retrying cannot guarantee timing; the application can't know when replication finishes.","D":"Transactional reads provide ACID consistency within a region but do not solve cross-region replication latency."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["dynamodb","global-tables","consistency","replication-lag"],"verified":true},{"id":"01-c1e3g5i7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"DynamoDB Global Tables","difficulty":"hard","question":"Concurrent writes to the same DynamoDB Global Table item occur from us-east-1 and eu-west-1 at nearly the same time. How does DynamoDB resolve the conflict?","options":{"A":"The write from the higher-traffic region wins","B":"DynamoDB rejects both writes and returns a conflict error","C":"Last writer wins — the write with the most recent timestamp is kept","D":"The first write to arrive at any region wins; subsequent writes are rejected"},"correct":"C","explanation":"DynamoDB Global Tables uses 'last writer wins' conflict resolution based on timestamps. When a conflict is detected during replication (two writes to the same item from different regions), the write with the later timestamp is kept and propagated to all regions. Applications that cannot tolerate this should use conditional writes.","distractors":{"A":"DynamoDB does not consider region traffic volume in conflict resolution; only timestamps matter.","B":"DynamoDB accepts writes from all regions simultaneously; it does not reject concurrent writes.","D":"DynamoDB does not use a locking mechanism that would reject subsequent writes; it accepts all and resolves via last-writer-wins."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["dynamodb","global-tables","conflict-resolution","last-writer-wins"],"verified":true},{"id":"01-d3f5h7j9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"DynamoDB Global Tables","difficulty":"medium","question":"A DynamoDB Global Table has replicas in us-east-1 and eu-west-1. One region becomes completely unavailable. What happens to write traffic?","options":{"A":"DynamoDB automatically routes writes from the failed region to the nearest healthy region","B":"Writes to the failed region fail; the application must redirect traffic to another region via Route 53 or application logic","C":"Global Tables automatically promotes another region as primary","D":"DynamoDB pauses all writes globally until the failed region recovers"},"correct":"B","explanation":"DynamoDB Global Tables does not automatically reroute writes on regional failure; the application must detect the failure and direct traffic to a healthy region. Route 53 health checks can automate DNS failover, or the application can implement region failover logic. Each region operates independently and accepts writes when healthy.","distractors":{"A":"DynamoDB SDK fails with an error if the target region is unavailable; transparent rerouting is not built in.","C":"Global Tables has no concept of a primary region — all regions are equal in active-active mode; there is no automatic promotion.","D":"DynamoDB does not pause global writes; healthy regions continue operating while the failed region is unavailable."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/GlobalTables.html","tags":["dynamodb","global-tables","failover","regional-failure"],"verified":true},{"id":"01-e5g7i9k1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"DynamoDB Global Tables","difficulty":"easy","question":"What is a prerequisite for enabling DynamoDB Global Tables on an existing table?","options":{"A":"The table must use provisioned capacity mode","B":"DynamoDB Streams must be enabled with NEW_AND_OLD_IMAGES stream view type","C":"The table must have a composite primary key (partition + sort key)","D":"The table must be encrypted with a customer-managed KMS key"},"correct":"B","explanation":"DynamoDB Streams must be enabled before converting a table to a Global Table, because Global Tables uses Streams internally to replicate changes across regions. The stream must be configured with the NEW_AND_OLD_IMAGES view type so the replication mechanism can propagate both creates and updates correctly.","distractors":{"A":"Global Tables supports both provisioned and on-demand capacity modes; provisioned is not required.","C":"Global Tables works with both simple (partition key only) and composite primary keys.","D":"Customer-managed KMS encryption is not a prerequisite for Global Tables, though it is supported."},"source_url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/globaltables_reqs_bestpractices.html","tags":["dynamodb","global-tables","streams","prerequisites"],"verified":true},{"id":"01-f7h9j1l3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"easy","question":"A web application on an Auto Scaling group spanning 3 AZs generates user-uploaded content that must be accessible to all instances simultaneously. Which storage solution enables this?","options":{"A":"EBS volume mounted to all EC2 instances simultaneously","B":"Amazon EFS file system mounted on all EC2 instances","C":"Instance store volumes on each EC2 instance","D":"S3 bucket accessed directly by the application code"},"correct":"B","explanation":"Amazon EFS is a fully managed NFS file system mountable on thousands of EC2 instances across all AZs within a region simultaneously. All instances see the same file system and changes are immediately visible to all mount points. EFS automatically scales capacity as files are added or deleted.","distractors":{"A":"EBS volumes attach to one EC2 instance at a time (except io1/io2 Multi-Attach with specific constraints); standard EBS cannot be shared across instances.","C":"Instance store is ephemeral local storage destroyed when an instance stops or terminates; data cannot be shared across instances.","D":"S3 is object storage, not a POSIX file system; applications expecting standard file system semantics cannot use S3 directly without code changes."},"source_url":"https://docs.aws.amazon.com/efs/latest/ug/whatisefs.html","tags":["efs","shared-storage","auto-scaling","nfs","multi-az"],"verified":true},{"id":"01-a9c1e3g5","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"medium","question":"A media company stores large video files on EFS, accessed intensively for the first 30 days then rarely. Which EFS configuration reduces costs while maintaining performance for recent uploads?","options":{"A":"EFS Standard with Provisioned Throughput of 1 GB/s","B":"EFS with Intelligent-Tiering — active files in Standard, cold files auto-transitioned to Infrequent Access","C":"EFS One Zone storage class for all files","D":"EFS Standard-Infrequent Access (Standard-IA) for all files"},"correct":"B","explanation":"EFS Intelligent-Tiering automatically moves files not accessed for 30 days to the cheaper Standard-IA storage class, then moves them back when accessed again. Recent uploads stay in Standard for full performance while old files transition automatically. This is the most cost-effective approach without manual management.","distractors":{"A":"Provisioned Throughput guarantees throughput for billing purposes but does not reduce storage costs for infrequent data; it would increase overall cost.","C":"EFS One Zone stores data in a single AZ, reducing cost but also durability; it does not address access pattern optimization.","D":"Moving all files to Standard-IA penalizes active files with higher read latency and retrieval charges; Intelligent-Tiering avoids this."},"source_url":"https://docs.aws.amazon.com/efs/latest/ug/lifecycle-management-efs.html","tags":["efs","intelligent-tiering","infrequent-access","cost-optimization"],"verified":true},{"id":"01-b1d3f5h7","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"hard","question":"An HPC cluster on EC2 needs shared storage with the lowest possible latency for random I/O with a custom MPI application. Which EFS configuration is optimal?","options":{"A":"EFS General Purpose performance mode with Bursting Throughput","B":"EFS Max I/O performance mode with Provisioned Throughput","C":"EFS General Purpose performance mode with Elastic Throughput","D":"EFS One Zone with Max I/O performance mode"},"correct":"C","explanation":"EFS General Purpose mode provides the lowest per-operation latency — critical for random I/O in HPC. Elastic Throughput automatically scales throughput based on workload without requiring pre-provisioning or credit accumulation. Max I/O offers higher aggregate throughput for massively parallel reads but at the cost of higher per-operation latency, hurting random I/O performance.","distractors":{"B":"Max I/O mode increases aggregate throughput for highly parallel workloads but at higher per-operation latency; for random I/O where latency matters, General Purpose is better.","A":"Bursting Throughput uses credits that must be accumulated; for sustained HPC workloads, Elastic Throughput is more reliable and doesn't depend on burst credits.","D":"One Zone reduces cost and durability by storing data in a single AZ; not appropriate for critical HPC production workloads."},"source_url":"https://docs.aws.amazon.com/efs/latest/ug/performance.html","tags":["efs","hpc","performance-mode","throughput","latency"],"verified":true},{"id":"01-c3e5g7i9","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"medium","question":"EC2 instances in us-east-1c have higher EFS latency than instances in us-east-1a and us-east-1b. What is the likely cause?","options":{"A":"EFS does not support the us-east-1c AZ","B":"The EFS mount target in us-east-1c is missing; instances mount through a cross-AZ network path","C":"EFS throughput is unevenly distributed across AZs","D":"The security group on the us-east-1c mount target is throttling connections"},"correct":"B","explanation":"EFS mount targets should be created in each AZ where EC2 instances reside. If a mount target is missing in us-east-1c, instances in that AZ mount via a mount target in a different AZ, adding cross-AZ network latency (typically 1-2ms additional). Creating a mount target in each AZ is the EFS best practice.","distractors":{"A":"EFS supports all AZs within a region; there is no AZ exclusion.","C":"EFS throughput is not unevenly distributed by AZ; the issue is network latency from cross-AZ access, not throughput allocation.","D":"Security groups allow or deny traffic but do not apply rate limiting or throttling in AWS."},"source_url":"https://docs.aws.amazon.com/efs/latest/ug/mounting-fs.html","tags":["efs","mount-target","cross-az","latency"],"verified":true},{"id":"01-d5f7h9j1","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"easy","question":"Which statement about Amazon EFS Standard storage class durability is correct?","options":{"A":"EFS Standard stores data in a single AZ with 99.9% availability","B":"EFS Standard stores data redundantly across multiple AZs within a region","C":"EFS automatically backs up to S3 across regions","D":"EFS durability depends on the RAID configuration of underlying instances"},"correct":"B","explanation":"Amazon EFS Standard storage class stores data redundantly across multiple Availability Zones within a region. This means EFS is resilient to an AZ failure without any additional configuration. The redundancy is handled transparently by the managed service — users do not configure it.","distractors":{"A":"Single-AZ storage is the EFS One Zone storage class, not Standard. EFS Standard spans multiple AZs.","C":"EFS does not automatically back up cross-region; AWS Backup can create backups but they are not cross-region by default.","D":"EFS is fully managed; users do not configure RAID or any storage-level redundancy."},"source_url":"https://docs.aws.amazon.com/efs/latest/ug/whatisefs.html","tags":["efs","durability","multi-az","redundancy"],"verified":true},{"id":"01-e7g9i1k3","version":"2026-05","setId":"set-01-resilient-architectures","domain":"Resilient Architectures","topic":"EFS for shared storage across AZs","difficulty":"medium","question":"A Windows-based application on EC2 needs shared file storage accessible from multiple instances using SMB protocol. Can Amazon EFS satisfy this?","options":{"A":"Yes — EFS supports both NFS and SMB protocols","B":"No — EFS only supports NFS; use Amazon FSx for Windows File Server for SMB","C":"Yes — EFS supports SMB on Windows EC2 instances with the EFS Windows client","D":"No — EFS cannot be mounted on Windows instances at all"},"correct":"B","explanation":"Amazon EFS only supports NFS (Network File System) and is designed for Linux workloads. Windows applications requiring SMB (Server Message Block) should use Amazon FSx for Windows File Server, which is fully managed, supports SMB, DFS namespaces, Active Directory integration, and all Windows file system features.","distractors":{"A":"EFS does not support SMB; it is NFS-only.","C":"There is no 'EFS Windows client' enabling SMB; the correct AWS-native solution for Windows SMB workloads is FSx for Windows File Server.","D":"EFS can technically be mounted on Windows using NFS client software, but FSx for Windows is the recommended solution for SMB workloads."},"source_url":"https://docs.aws.amazon.com/fsx/latest/WindowsGuide/what-is.html","tags":["efs","fsx","windows","smb","nfs"],"verified":true}]`);export{e as default};